function aboutBlock(c){
  const kicker=lang==='zh'?'关于 Z LAB':'ABOUT Z LAB';
  const labels=lang==='zh'?['团队分工','怎么合作']:['THE TEAM','HOW WE WORK'];
  const groups=(c.teamGroups&&c.teamGroups.length)?c.teamGroups:(lang==='zh'?[
    ['技术与交付 / 2 人','创始人 Z 与另一位技术负责人','负责需求梳理、技术方案、开发与交付，并参与项目对接。'],
    ['客户与合作 / 2 人','两位市场负责人','负责介绍服务、沟通需求、寻找合作机会，并把需求带回团队确认。']
  ]:[
    ['TECHNOLOGY & DELIVERY / 2','Founder Z and one technical lead','Scope the need, choose the approach, build and deliver, and stay in the project conversation.'],
    ['CLIENTS & PARTNERSHIPS / 2','Two growth leads','Explain the services, discuss needs and partnerships, and bring the brief back to the team.']
  ]);
  const title=c.teamTitle||(lang==='zh'?'四个人，<br><em>各自负责哪一步。</em>':'Four people,<br><em>clear responsibilities.</em>');
  const intro=c.teamIntro||(lang==='zh'?'技术和客户沟通由团队成员直接负责，项目开始前会确认对接与交付的人是谁。':'Team members handle the technical work and the client conversations directly, and we agree who owns contact and delivery before a project starts.');
  const steps=lang==='zh'
    ?['一封邮件说明目标、已有材料和时间节点。','确认交付内容、第三方费用与时间安排。','按约定范围开发，过程中同步进展。','一起检查交付内容并说明使用方法。']
    :['One email with the goal, what you have and your timeline.','We agree the deliverable, third party costs and timing.','We build within the agreed scope and keep you posted.','We review the result together and explain how to use it.'];
  return '<section class="x-about" id="about"><div class="x-about-inner"><header class="x-about-head"><p class="x-about-kicker">'+kicker+'</p><h2>'+title+'</h2><p class="x-about-intro">'+intro+'</p></header><div class="x-about-grid"><div class="x-about-cell"><p class="x-about-label">'+labels[0]+'</p>'+groups.map(function(g){return '<article><span>'+g[0]+'</span><strong>'+g[1]+'</strong><p>'+g[2]+'</p></article>'}).join('')+'</div><div class="x-about-cell"><p class="x-about-label">'+labels[1]+'</p><ol>'+steps.map(function(step){return '<li>'+step+'</li>'}).join('')+'</ol></div></div></div></section>';
}
