 if(kind==='sodium') return '<section class="poster poster-sodium"><div class="poster-sodium-head"><span>THE Z LAB CATALOGUE</span><span class="x-demo-chip">视觉演示 / VISUAL DEMO</span></div><div class="poster-sodium-grid"><div class="poster-sodium-number">03</div><div class="poster-sodium-title"><h1>'+p.sodiumTitle+'</h1><span>'+p.sub+'</span><a href="'+mailtoHref+'">'+p.contact+' ↗</a></div></div><div class="poster-sodium-products">'+p.services.map((x,i)=>'<div class="sodium-tile tile-'+i+'"><b>'+x[0]+'</b><strong>'+x[1]+'</strong><span>'+x[2]+'</span><i>'+(i+1)+'</i></div>').join('')+'</div></section>';
 if(kind==='snow') return '<section class="poster poster-snow"><div class="poster-snow-top"><b>Z LAB</b><span class="x-demo-chip">视觉演示 / VISUAL DEMO</span></div><div class="poster-snow-ribbon"><span>AI</span><span>DESIGN</span><span>AGENTS</span><span>3D</span><span>AI</span><span>DESIGN</span><span>AGENTS</span><span>3D</span></div><div class="poster-snow-grid"><div class="poster-snow-copy"><h1>'+p.snowTitle+'</h1><p>'+p.sub+'</p><a href="'+mailtoHref+'">'+p.contact+' ↗</a></div><div class="poster-snow-orbit"><div class="snow-orbit-core">Z</div><i class="snow-orbit-ring ring-a"></i><i class="snow-orbit-ring ring-b"></i></div></div><div class="poster-snow-services">'+p.services.map((x,i)=>'<a href="'+mailtoHref+'"><small>'+x[0]+'</small><b>'+x[1]+'</b><span>'+x[2]+'</span><i>↗</i></a>').join('')+'</div></section>';
