function origin(c){return '<div class="variant-page page-origin origin-v2">'+posterMarkup('origin')+'<div class="origin-pulse"><span>WEBSITE</span><span>AI TOOL</span><span>COURSEWORK</span><span>DATA</span><span>WEBSITE</span><span>AI TOOL</span></div><section class="origin-rail variant-pad" id="services"><aside><small>02 / OFFER · 界面演示 VISUAL DEMO</small><h2>'+c.sectionTitle+'</h2><p>'+c.briefText+'</p></aside><div class="origin-rail-list">'+c.services.map(function(x,i){return '<article><span>'+x[0]+'</span><div><h3>'+x[1]+'</h3><p>'+x[2]+'</p></div><b>0'+(i+1)+'</b></article>'}).join('')+'</div></section><section class="origin-ledger variant-pad" id="work"><div class="origin-ledger-head"><small>03 / TEAM &amp; SCOPE</small><h2>'+c.proofTitle+'</h2></div><div class="origin-ledger-numbers">'+c.proofs.map(function(x){return '<div><strong>'+x[0]+'</strong><span>'+x[1]+'</span></div>'}).join('')+'</div></section><section class="origin-price-strip variant-pad"><small>04 / QUOTE BASIS · 报价依据</small><div>'+c.pricing.map(function(x){return '<span><b>'+x[0]+'</b> '+x[1]+'</span>'}).join('')+'</div></section>'+aboutBlock(c)+'<section class="origin-cta origin-cta-v2 variant-pad" id="contact"><p>05 / START PROJECT</p><h2>'+c.contactTitle+'</h2><span>'+c.contactNote+'</span>'+link(c.button)+'</section></div>'}
function skeg(c){return '<div class="variant-page page-skeg">'+posterMarkup('skeg')+'<section class="skeg-cases variant-pad" id="work"><div class="skeg-case-head"><span>界面演示 / VISUAL DEMO</span><span>CONCEPT ONLY</span></div><p class="zs-demo-note">'+c.demoNote+'</p>'+c.cases.map(x=>'<a class="skeg-case" href="#contact"><span>'+x[0]+'</span><div><small>'+x[2]+'</small><h2>'+x[1]+'</h2><p>'+x[3]+'</p></div><b>↗</b></a>').join('')+'</section><section class="skeg-notes variant-pad" id="studio"><p class="skeg-label">THE STUDIO</p><h2>'+c.noteTitle+'</h2><div>'+c.notes.map((x,i)=>'<article><span>0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></article>').join('')+'</div></section>'+aboutBlock(c)+'<section class="skeg-end variant-pad" id="contact"><p class="skeg-label">GET IN TOUCH</p><h2>'+c.contactTitle+'</h2><p>'+c.contactText+'</p><a href="'+mailtoHref+'">'+c.contact+' ↗</a></section></div>'}
function good(c){return '<div class="variant-page page-good">'+posterMarkup('good-tech')+'<div class="good-ticker"><span>'+c.ticker+'</span></div><section class="good-steps variant-pad" id="services"><p class="zs-demo-note">'+c.demoNote+'</p>'+c.steps.map(x=>'<article><small>'+x[0]+'</small><div><span>'+x[1]+'</span><h2>'+x[2]+'</h2><p>'+x[3]+'</p></div><b>↗</b></article>').join('')+'</section><section class="good-proof variant-pad" id="work">'+c.proofs.map(x=>'<div><strong>'+x[0]+'</strong><span>'+x[1]+'</span></div>').join('')+'</section>'+aboutBlock(c)+'<section class="good-cta variant-pad" id="contact"><p>GOOD TECH / Z LAB</p><h2>'+c.cta+'</h2>'+link(c.button)+'</section></div>'}
function unitar(c){const note=demoNote('line');return '<div class="variant-page page-unitar">'+posterMarkup('unitar')+'<section class="unitar-modules variant-pad" id="work"><div class="unitar-module-head"><span>./SKILLS</span><h2>BUILD<br />SOMETHING.</h2></div><div class="unitar-module-grid">'+c.modules.map(x=>'<article><small>'+x[0]+'</small><h3>'+x[1]+'</h3><p>'+x[2]+'</p><b>↗</b></article>').join('')+'</div></section><section class="unitar-log variant-pad" id="studio"><div><span>'+c.logTitle+'</span><h2>SHIP LOG</h2></div>'+note+'<ol>'+c.logs.map((x,i)=>'<li><b>0'+(i+1)+'</b><span>'+x+'</span><i>'+(lang==='zh'?'步骤':'step')+'</i></li>').join('')+'</ol></section>'+aboutBlock(c)+'<section class="unitar-command variant-pad" id="contact"><code><span>$</span> '+c.command+'<br /><b>'+c.out+'</b></code><a href="'+mailtoHref+'">'+c.cta+' ↗</a></section></div>'}
function sodium(c){const note=demoNote('name');return '<div class="variant-page page-sodium">'+posterMarkup('sodium')+'<section class="sodium-index variant-pad" id="work">'+note+'<div class="sodium-index-head"><span>Z LAB / SMALL TOOLS</span><span class="zs-demo-tag">视觉演示 / VISUAL DEMO</span></div>'+c.products.map((x,i)=>'<a class="sodium-product" href="#contact"><span>'+x[0]+'</span><div><small>'+x[2]+'</small><h2>'+x[1]+'</h2><p>'+x[3]+'</p></div><b class="sodium-product-art art-'+i+'">'+(i+1)+'</b><em>↗</em></a>').join('')+'</section><section class="sodium-statement variant-pad" id="studio"><span>THE STUDIO</span><h2>'+c.statement+'</h2><div><b>Z LAB</b><p>Small software, made with care.</p></div></section>'+aboutBlock(c)+'<section class="sodium-contact variant-pad" id="contact"><h2>'+c.cta+'</h2><a href="'+mailtoHref+'">'+mail+' ↗</a></section></div>'}
function snow(c){const note=demoNote('page');return '<div class="variant-page page-snow">'+posterMarkup('snow')+'<div class="snow-marquee"><span>'+c.capabilities.join(' / ')+' / '+c.capabilities.join(' / ')+'</span></div><section class="snow-grid variant-pad" id="work">'+note+'<div class="snow-grid-head"><span>视觉演示 / VISUAL DEMO</span><h2>Made to be<br><em>remembered.</em></h2></div><div class="snow-cases">'+c.cases.map((x,i)=>'<a href="#contact" class="snow-case snow-case-'+i+'"><small>'+x[0]+'</small><h3>'+x[1]+'</h3><p>'+x[2]+'</p><b>↗</b></a>').join('')+'</div></section><section class="snow-process variant-pad" id="services"><p>OUR PROCESS</p><div>'+c.process.map((x,i)=>'<span><b>0'+(i+1)+'</b>'+x+'</span>').join('')+'</div></section>'+aboutBlock(c)+'<section class="snow-cta variant-pad" id="contact"><h2>'+c.cta+'</h2><a href="'+mailtoHref+'">'+mail+' ↗</a></section></div>'}
function market(c){const note=demoNote('poster');return '<div class="variant-page page-market">'+posterMarkup('market')+'<section class="market-capabilities variant-pad" id="services"><div class="market-heading"><span>CAPABILITIES</span><h2>What we bring<br><em>to the table.</em></h2></div><div class="market-cap-list">'+c.capabilities.map((x,i)=>'<article><span>0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p><b>↗</b></article>').join('')+'</div></section><section class="market-engage variant-pad" id="work">'+note+'<div>'+c.engage.map(x=>'<article><small>'+x[0]+'</small><h3>'+x[1]+'</h3><p>'+x[2]+'</p></article>').join('')+'</div></section>'+aboutBlock(c)+'<section class="market-cta variant-pad" id="contact"><p>LET’S BUILD THE NEXT VERSION</p><h2>'+c.ctaTitle+'</h2><span>'+c.ctaText+'</span><a href="'+mailtoHref+'">'+mail+' ↗</a></section></div>'}
function hermes(c){
 const emailHref='mailto:'+mail+'?subject='+encodeURIComponent(c.mailSubject)+'&amp;body='+encodeURIComponent(c.mailBody);
 return `<div class="variant-page page-hermes">
  <section class="hermes-hero" aria-labelledby="hermes-title">
   <div class="hermes-hero-grid">
    <div class="hermes-hero-copy">
     <p class="hermes-eyebrow"><span class="hermes-spark" aria-hidden="true">✳</span>${c.kicker}</p>
     <h1 id="hermes-title">${c.heroTitle}</h1>
     <p class="hermes-hero-lede">${c.heroText}</p>
     <div class="hermes-hero-actions"><a class="hermes-action hermes-action-primary" href="${emailHref}">${c.primary}<span aria-hidden="true">↗</span></a><a class="hermes-action hermes-action-secondary" href="#work">${c.secondary}<span aria-hidden="true">↓</span></a></div>
    </div>
    <div class="hermes-art" aria-hidden="true"><div class="hermes-rays"></div><div class="hermes-art-ring hermes-art-ring-outer"></div><div class="hermes-art-ring hermes-art-ring-inner"></div><span class="hermes-art-z">Z</span><span class="hermes-art-orbit">${c.heroOrbit}</span><span class="hermes-art-star">✳</span></div>
   </div>
   <div class="hermes-hero-rule"><span>${c.heroIndex}</span><span>Z LAB © 2026</span></div>
   <div class="hermes-brief"><div class="hermes-brief-heading"><p>${c.briefEyebrow}</p><h2>${c.briefTitle}</h2></div><div class="hermes-brief-items">${c.briefItems.map(x=>`<div><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div><a href="${emailHref}">${c.briefCta}<span aria-hidden="true">↗</span></a></div>
  </section>
  <section class="hermes-work hermes-section" id="work"><div class="hermes-section-head"><p class="hermes-section-label">${c.workEyebrow}</p><div><h2>${c.workTitle}</h2><p>${c.workIntro}</p></div></div><div class="hermes-case-list">${c.caseStudies.map((item,i)=>`<article class="hermes-case"><div class="hermes-case-visual" aria-hidden="true"><div class="hermes-case-browser"><span></span><span></span><span></span><div class="hermes-case-screen"><b>Z</b><i></i><i></i><i></i></div></div><small>Z LAB / ${String(i+1).padStart(2,'0')}</small></div><div class="hermes-case-content"><p class="hermes-case-kind">${item.kind}</p><h3>${item.title}</h3><dl><div><dt>${c.caseLabels[0]}</dt><dd>${item.problem}</dd></div><div><dt>${c.caseLabels[1]}</dt><dd>${item.work}</dd></div><div><dt>${c.caseLabels[2]}</dt><dd>${item.outcome}</dd></div></dl><a href="${item.href}">${item.cta} <span aria-hidden="true">↗</span></a></div></article>`).join('')}</div><h3 class="hermes-path-heading">${c.pathsTitle}</h3><div class="hermes-path-grid">${c.paths.map(x=>`<article class="hermes-path-card"><span class="hermes-path-number">${x[0]}</span><div><p>${x[3]}</p><h3>${x[1]}</h3><span>${x[2]}</span></div></article>`).join('')}</div></section>
  <section class="hermes-services hermes-section" id="services"><div class="hermes-section-head"><p class="hermes-section-label">${c.servicesEyebrow}</p><div><h2>${c.servicesTitle}</h2><p>${c.servicesIntro}</p></div></div><div class="hermes-service-list">${c.services.map((x,i)=>`<div class="hermes-service-row"><span class="hermes-service-number">${String(i+1).padStart(2,'0')}</span><span class="hermes-service-category">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section>
  <section class="hermes-studio hermes-section" id="studio"><div class="hermes-studio-intro"><p class="hermes-section-label">${c.studioEyebrow}</p><h2>${c.studioTitle}</h2><p>${c.studioIntro}</p><div class="hermes-studio-mark" aria-hidden="true">Z<span>LAB</span></div></div><div class="hermes-step-list">${c.steps.map(x=>`<article><small>${x[0]}</small><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div></section>
  <section class="hermes-team hermes-section"><div class="hermes-section-head"><p class="hermes-section-label">${c.teamEyebrow}</p><div><h2>${c.teamTitle}</h2><p>${c.teamIntro}</p></div></div><div class="hermes-team-grid">${c.teamGroups.map((x,i)=>`<article><span>0${i+1} / 02</span><h3>${x[0]}</h3><strong>${x[1]}</strong><p>${x[2]}</p></article>`).join('')}</div></section>
  <section class="hermes-pricing hermes-section"><div class="hermes-section-head"><p class="hermes-section-label">${c.pricingEyebrow}</p><div><h2>${c.pricingTitle}</h2><p>${c.pricingIntro}</p></div></div><div class="hermes-pricing-points">${c.pricingPoints.map((x,i)=>`<article><small>0${i+1}</small><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div><p class="hermes-pricing-note">${c.pricingNote}</p></section>
  <section class="hermes-faq hermes-section"><div><p class="hermes-section-label">${c.faqEyebrow}</p><h2>${c.faqTitle}</h2></div><div class="hermes-faq-list">${c.faqs.map(x=>`<details><summary>${x[0]}<span aria-hidden="true">+</span></summary><p>${x[1]}</p></details>`).join('')}</div></section>
  <section class="hermes-contact hermes-section" id="contact"><p class="hermes-section-label">${c.contactEyebrow}</p><h2>${c.contactTitle}</h2><div class="hermes-contact-bottom"><p>${c.contactIntro}</p><a class="hermes-action hermes-action-primary" href="${emailHref}">${c.contactCta}<span aria-hidden="true">↗</span></a></div></section>
 </div>`;
}
