const renderers={'z-signal':zSignal,unrushed,origin,skeg,'good-tech':good,unitar,sodium,'snow-fox':snow,market,hermes};
let observer;
let zSignalCleanup=()=>{};
function observeReveal(){if(observer)observer.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal,.variant-page [data-reveal]').forEach(el=>observer.observe(el))}
if('scrollRestoration' in history)history.scrollRestoration='manual';
function applyStyle(next,resetScroll=true){style=next in renderers?next:'z-signal';mailtoHref=mailto(null);root.dataset.style=style;document.body.className='style-'+style;styleCurrent.textContent=styleNames[style];styleOptions.forEach(option=>option.classList.toggle('is-active',option.dataset.style===style));main.innerHTML=renderers[style](style==='z-signal'?zSignalCopy[lang]:pageCopy[styleKey[style]][lang]);applyNavIds();main.querySelectorAll('[data-reveal]').forEach(el=>el.classList.add('reveal'));applyNav(style);localStorage.setItem('zlab-style',style);observeReveal();bindDynamicEffects();if(resetScroll)window.scrollTo({top:0,behavior:'smooth'})}
function closeStylePanel(){stylePanel.hidden=true;styleToggle.setAttribute('aria-expanded','false')}
langToggle.addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';renderChrome();applyStyle(style,false)});themeToggle.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';localStorage.setItem('zlab-theme',root.dataset.theme);themeToggle.setAttribute('aria-pressed',String(root.dataset.theme==='light'))});styleToggle.addEventListener('click',()=>{const open=stylePanel.hidden;stylePanel.hidden=!open;styleToggle.setAttribute('aria-expanded',String(open))});styleOptions.forEach(option=>option.addEventListener('click',()=>{applyStyle(option.dataset.style);closeStylePanel()}));document.addEventListener('click',event=>{if(!event.target.closest('.style-picker'))closeStylePanel()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeStylePanel()});renderChrome();root.dataset.theme=localStorage.getItem('zlab-theme')||'dark';themeToggle.setAttribute('aria-pressed',String(root.dataset.theme==='light'));applyStyle(style,false);


function bindZSignalCanvas(){
  const canvas=document.querySelector('[data-zs-canvas]');
  const hero=document.querySelector('.zs-hero');
  if(!canvas||!hero)return;
  const ctx=canvas.getContext('2d');
  if(!ctx)return;
  const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let width=0,height=0,dpr=1,raf=0,time=0;
  const pointer={x:.5,y:.5,tx:.5,ty:.5};
  let stars=[];
  const resize=()=>{const rect=hero.getBoundingClientRect();width=Math.max(1,rect.width);height=Math.max(1,rect.height);dpr=Math.min(window.devicePixelRatio||1,1.65);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);canvas.style.width=width+'px';canvas.style.height=height+'px';ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:230},(_,i)=>({a:Math.random()*Math.PI*2,r:Math.sqrt(Math.random()),z:Math.random(),s:.4+Math.random()*1.4,p:Math.random()*Math.PI*2,i}))};
  const draw=(stamp=0)=>{time=stamp*.001;ctx.clearRect(0,0,width,height);pointer.x+=(pointer.tx-pointer.x)*.06;pointer.y+=(pointer.ty-pointer.y)*.06;const cx=width*(.63+(pointer.x-.5)*.03),cy=height*(.5+(pointer.y-.5)*.02),rx=Math.min(width*.36,520),ry=Math.min(height*.46,460);const gradient=ctx.createRadialGradient(cx,cy,0,cx,cy,Math.max(rx,ry));gradient.addColorStop(0,'rgba(216,255,62,.68)');gradient.addColorStop(.16,'rgba(216,255,62,.18)');gradient.addColorStop(.44,'rgba(114,103,255,.08)');gradient.addColorStop(1,'rgba(10,11,15,0)');ctx.fillStyle=gradient;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,-.23,0,Math.PI*2);ctx.fill();ctx.save();ctx.translate(cx,cy);ctx.rotate(-.23);for(let i=0;i<13;i++){const f=.17+i/14*.88;ctx.beginPath();ctx.ellipse(0,0,rx*f,ry*f,0,0,Math.PI*2);ctx.strokeStyle=i%3===0?'rgba(216,255,62,.2)':'rgba(243,240,233,.06)';ctx.lineWidth=i%4===0?1:.6;ctx.setLineDash([2+i*.5,10+i*1.6]);ctx.lineDashOffset=-time*(i%2?8:-6);ctx.stroke()}ctx.setLineDash([]);ctx.restore();const points=[];stars.forEach(star=>{const depth=.36+star.z*.92;const angle=star.a+time*.04+star.z*.36;const x=cx+Math.cos(angle)*rx*star.r*depth+(pointer.x-.5)*45;const y=cy+Math.sin(angle*1.12+star.z)*ry*star.r*depth+(pointer.y-.5)*26+Math.sin(time*.8+star.p)*4;points.push([x,y,star]);ctx.globalAlpha=(.14+star.z*.7)*(.8+Math.sin(time*1.1+star.p)*.2);ctx.fillStyle=star.i%9===0?'#d8ff3e':'#f3f0e9';ctx.beginPath();ctx.arc(x,y,Math.max(.5,star.s*depth),0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.lineWidth=.65;for(let i=0;i<points.length;i+=7){const a=points[i],b=points[(i+17)%points.length];if(Math.hypot(a[0]-b[0],a[1]-b[1])<Math.max(rx,ry)*.16){ctx.strokeStyle='rgba(216,255,62,.15)';ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke()}}ctx.save();ctx.translate(cx,cy);ctx.rotate(-.23+Math.sin(time*.28)*.03);ctx.strokeStyle='rgba(216,255,62,.58)';ctx.lineWidth=1.2;ctx.setLineDash([3,13]);ctx.beginPath();ctx.moveTo(-rx*.48,-ry*.3);ctx.lineTo(rx*.45,-ry*.3);ctx.lineTo(-rx*.45,ry*.3);ctx.lineTo(rx*.48,ry*.3);ctx.stroke();ctx.restore();if(!reduce)raf=requestAnimationFrame(draw)};
  const onMove=e=>{const rect=hero.getBoundingClientRect();pointer.tx=(e.clientX-rect.left)/rect.width;pointer.ty=(e.clientY-rect.top)/rect.height;hero.style.setProperty('--zs-x',((pointer.tx-.5)*28).toFixed(1)+'px');hero.style.setProperty('--zs-y',((pointer.ty-.5)*21).toFixed(1)+'px')};
  const onLeave=()=>{pointer.tx=.5;pointer.ty=.5;hero.style.setProperty('--zs-x','0px');hero.style.setProperty('--zs-y','0px')};
  const observer=new ResizeObserver(resize);observer.observe(hero);resize();hero.addEventListener('pointermove',onMove);hero.addEventListener('pointerleave',onLeave);draw(0);
  zSignalCleanup=()=>{cancelAnimationFrame(raf);observer.disconnect();hero.removeEventListener('pointermove',onMove);hero.removeEventListener('pointerleave',onLeave);zSignalCleanup=()=>{}};
}

function bindDynamicEffects(){
  zSignalCleanup();
  bindZSignalCanvas();
  document.querySelectorAll('.page-snow, .page-good, .poster-origin').forEach(page=>{
    const visual=page.matches('.poster-origin')?page:page.querySelector('.snow-orb, .good-hero-shape, .poster-snow-orbit, .poster-good-console');
    if(!visual)return;
    page.addEventListener('pointermove',event=>{
      const rect=page.getBoundingClientRect();
      const x=((event.clientX-rect.left)/rect.width-.5)*18;
      const y=((event.clientY-rect.top)/rect.height-.5)*18;
      visual.style.setProperty('--mx',x.toFixed(1)+'px');
      visual.style.setProperty('--my',y.toFixed(1)+'px');
    });
    page.addEventListener('pointerleave',()=>{visual.style.setProperty('--mx','0px');visual.style.setProperty('--my','0px')});
  });
}
